 cs=[c for c in range(18) if grid[r][c]==4]
 if len(cs)>1:
  for a,b in zip(cs,cs[1:]):
   fills.update((r,c) for c in range(a+1,b))
for c in range(18):
 rs=[r for r in range(12) if grid[r][c]==4]
